"use client"
import { useMemo, useState } from "react"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Checkbox } from "@atlas/ui-web/primitives/Checkbox/Checkbox"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import { Skeleton } from "@atlas/ui-web/primitives/Skeleton/Skeleton"
import {
  Select,
  SelectTrigger,
  SelectValue,
  SelectContent,
  SelectItem,
} from "@atlas/ui-web/primitives/Select/Select"
import {
  Table,
  TableHeader,
  TableBody,
  TableRow,
  TableHead,
  TableCell,
} from "@atlas/ui-web/primitives/Table/Table"
import {
  AlertDialog,
  AlertDialogContent,
  AlertDialogTitle,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogCancel,
  AlertDialogAction,
} from "@atlas/ui-web/compositions/AlertDialog/AlertDialog"
import { TabsRoot, TabsList, TabsTrigger } from "@atlas/ui-web/patterns/Tabs/Tabs"
import {
  INITIAL_INVOICES,
  NO_MATCH_QUERY,
  STATUS_LABEL,
  type Invoice,
  type InvoiceStatus,
  type StatusFilter,
} from "../schema"

type ReviewState = "live" | "loading" | "empty"

const STATUS_BADGE: Record<InvoiceStatus, "success" | "warning" | "danger"> = {
  paid: "success",
  pending: "warning",
  overdue: "danger",
}

const money = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" })
const dateFmt = new Intl.DateTimeFormat("en-GB", { day: "2-digit", month: "short", year: "numeric", timeZone: "UTC" })
const formatDate = (iso: string) => dateFmt.format(new Date(`${iso}T00:00:00Z`))

const SKELETON_ROWS = [0, 1, 2, 3, 4, 5]

export function InvoicesScreen() {
  const [invoices, setInvoices] = useState<Invoice[]>(INITIAL_INVOICES)
  const [query, setQuery] = useState("")
  const [status, setStatus] = useState<StatusFilter>("all")
  const [selected, setSelected] = useState<Set<string>>(new Set())
  const [loading, setLoading] = useState(false)
  const [confirmDelete, setConfirmDelete] = useState(false)

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase()
    return invoices.filter(
      (inv) =>
        (status === "all" || inv.status === status) &&
        (q === "" || inv.number.toLowerCase().includes(q) || inv.customer.toLowerCase().includes(q)),
    )
  }, [invoices, query, status])

  const selectedVisible = filtered.filter((inv) => selected.has(inv.id))
  const selectedCount = selectedVisible.length
  const allSelected = filtered.length > 0 && selectedCount === filtered.length
  const headChecked: boolean | "indeterminate" = allSelected ? true : selectedCount > 0 ? "indeterminate" : false

  const review: ReviewState = loading ? "loading" : filtered.length === 0 ? "empty" : "live"

  const setReview = (next: string) => {
    if (next === "loading") {
      setLoading(true)
    } else if (next === "empty") {
      setLoading(false)
      setQuery(NO_MATCH_QUERY)
      setStatus("all")
    } else {
      setLoading(false)
      setQuery("")
      setStatus("all")
    }
  }

  const clearFilters = () => {
    setQuery("")
    setStatus("all")
  }

  const toggleAll = (checked: boolean | "indeterminate") => {
    setSelected((prev) => {
      const next = new Set(prev)
      filtered.forEach((inv) => (checked === true ? next.add(inv.id) : next.delete(inv.id)))
      return next
    })
  }

  const toggleRow = (id: string, checked: boolean | "indeterminate") => {
    setSelected((prev) => {
      const next = new Set(prev)
      if (checked === true) next.add(id)
      else next.delete(id)
      return next
    })
  }

  const markPaid = () => {
    const ids = new Set(selectedVisible.map((inv) => inv.id))
    setInvoices((prev) => prev.map((inv) => (ids.has(inv.id) ? { ...inv, status: "paid" } : inv)))
    setSelected(new Set())
  }

  const deleteSelected = () => {
    const ids = new Set(selectedVisible.map((inv) => inv.id))
    setInvoices((prev) => prev.filter((inv) => !ids.has(inv.id)))
    setSelected(new Set())
    setConfirmDelete(false)
  }

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "var(--atlas-spacing-4)",
        paddingInline: "var(--atlas-spacing-4)",
        paddingBlock: "var(--atlas-spacing-4)",
        color: "var(--atlas-foreground)",
        fontFamily: "var(--atlas-font-sans)",
      }}
    >
      <h1
        style={{
          margin: 0,
          fontSize: "var(--atlas-text-h2)",
          fontWeight: "var(--atlas-font-weight-semibold)",
          lineHeight: "var(--atlas-line-height-tight)",
        }}
      >
        Invoices
      </h1>

      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1_5)" }}>
        <span
          style={{
            fontSize: "var(--atlas-text-caption)",
            color: "var(--atlas-foreground-muted)",
          }}
        >
          Review state
        </span>
        <TabsRoot variant="pill" size="sm" value={review} onValueChange={setReview}>
          <TabsList aria-label="Review state">
            <TabsTrigger value="live">Data</TabsTrigger>
            <TabsTrigger value="loading">Loading</TabsTrigger>
            <TabsTrigger value="empty">No matches</TabsTrigger>
          </TabsList>
        </TabsRoot>
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
        <Input
          type="search"
          size="md"
          placeholder="Search invoice or customer"
          aria-label="Search invoices"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />
        <Select value={status} onValueChange={(v) => setStatus(v as StatusFilter)}>
          <SelectTrigger size="md" aria-label="Filter by status">
            <SelectValue placeholder="Status" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All statuses</SelectItem>
            <SelectItem value="paid">Paid</SelectItem>
            <SelectItem value="pending">Pending</SelectItem>
            <SelectItem value="overdue">Overdue</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {selectedCount > 0 && review === "live" && (
        <div
          role="region"
          aria-label="Bulk actions"
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            flexWrap: "wrap",
            gap: "var(--atlas-spacing-2)",
            padding: "var(--atlas-spacing-2) var(--atlas-spacing-3)",
            background: "var(--atlas-surface-raised)",
            border: "var(--atlas-border-width-1) solid var(--atlas-border)",
            borderRadius: "var(--atlas-radius-md)",
            boxShadow: "var(--atlas-shadow-md)",
          }}
        >
          <span
            aria-live="polite"
            style={{
              fontSize: "var(--atlas-text-body-sm)",
              fontWeight: "var(--atlas-font-weight-medium)",
            }}
          >
            {selectedCount} selected
          </span>
          <div style={{ display: "flex", gap: "var(--atlas-spacing-2)" }}>
            <Button variant="secondary" size="sm" onClick={markPaid}>
              Mark as paid
            </Button>
            <Button variant="destructive" size="sm" onClick={() => setConfirmDelete(true)}>
              Delete
            </Button>
          </div>
        </div>
      )}

      <div
        role="region"
        aria-label="Invoices table"
        tabIndex={0}
        aria-busy={review === "loading"}
        style={{
          overflowX: "auto",
          border: "var(--atlas-border-width-1) solid var(--atlas-border)",
          borderRadius: "var(--atlas-radius-md)",
        }}
      >
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>
                <Checkbox
                  size="sm"
                  aria-label="Select all invoices"
                  checked={headChecked}
                  disabled={review !== "live"}
                  onCheckedChange={toggleAll}
                />
              </TableHead>
              <TableHead>Invoice</TableHead>
              <TableHead>Customer</TableHead>
              <TableHead align="end">Amount</TableHead>
              <TableHead>Status</TableHead>
              <TableHead>Due date</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {review === "loading" &&
              SKELETON_ROWS.map((i) => (
                <TableRow key={i}>
                  {[0, 1, 2, 3, 4, 5].map((c) => (
                    <TableCell key={c}>
                      <Skeleton style={{ minInlineSize: "var(--atlas-spacing-8)" }} />
                    </TableCell>
                  ))}
                </TableRow>
              ))}

            {review === "empty" && (
              <TableRow>
                <TableCell colSpan={6}>
                  <div
                    role="status"
                    style={{
                      display: "flex",
                      flexDirection: "column",
                      alignItems: "center",
                      gap: "var(--atlas-spacing-2)",
                      paddingBlock: "var(--atlas-spacing-8)",
                      textAlign: "center",
                    }}
                  >
                    <span
                      style={{
                        fontSize: "var(--atlas-text-h4)",
                        fontWeight: "var(--atlas-font-weight-semibold)",
                      }}
                    >
                      No invoices found
                    </span>
                    <span
                      style={{
                        fontSize: "var(--atlas-text-body-sm)",
                        color: "var(--atlas-foreground-muted)",
                      }}
                    >
                      No invoice matches your search or status filter.
                    </span>
                    <Button variant="outline" size="sm" onClick={clearFilters}>
                      Clear filters
                    </Button>
                  </div>
                </TableCell>
              </TableRow>
            )}

            {review === "live" &&
              filtered.map((inv) => (
                <TableRow key={inv.id} selected={selected.has(inv.id)}>
                  <TableCell>
                    <Checkbox
                      size="sm"
                      aria-label={`Select ${inv.number}`}
                      checked={selected.has(inv.id)}
                      onCheckedChange={(c) => toggleRow(inv.id, c)}
                    />
                  </TableCell>
                  <TableCell>{inv.number}</TableCell>
                  <TableCell>{inv.customer}</TableCell>
                  <TableCell align="end">{money.format(inv.amount)}</TableCell>
                  <TableCell>
                    <Badge variant={STATUS_BADGE[inv.status]} size="sm" dot>
                      {STATUS_LABEL[inv.status]}
                    </Badge>
                  </TableCell>
                  <TableCell>{formatDate(inv.dueDate)}</TableCell>
                </TableRow>
              ))}
          </TableBody>
        </Table>
      </div>

      <AlertDialog open={confirmDelete} onOpenChange={setConfirmDelete}>
        <AlertDialogContent variant="destructive" size="sm">
          <AlertDialogTitle>
            Delete {selectedCount} {selectedCount === 1 ? "invoice" : "invoices"}?
          </AlertDialogTitle>
          <AlertDialogDescription>
            This permanently removes the selected {selectedCount === 1 ? "invoice" : "invoices"}. This can’t be undone.
          </AlertDialogDescription>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={deleteSelected}>Delete</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

